/* Start [ MGCMTBLDAT Table(TABLE_NAME) : ATTRIBUTE_TYPE] */
BEGIN
   FOR REC IN (
       SELECT DISTINCT FACTORY FROM MWIPFACDEF
       MINUS
       SELECT DISTINCT FACTORY FROM MGCMTBLDAT
       WHERE TABLE_NAME = 'ATTRIBUTE_TYPE'
       AND KEY_1 = 'TOOL'
       )
   LOOP
   END LOOP;
END;
/
/* End [ MGCMTBLDAT Table(TABLE_NAME) : ATTRIBUTE_TYPE] */


