   FOR REC IN (
       SELECT DISTINCT FACTORY FROM MWIPFACDEF
       MINUS
       SELECT DISTINCT FACTORY FROM MBASGLBDEF
       WHERE OPTION_NAME = 'MP_RecalculateZeroQtyLotinRTD'
       )
   LOOP
    values (REC.FACTORY,'MP_RecalculateZeroQtyLotinRTD','Whether to recalculate zero qty Lot in RTD','N',' ',' ',' ',' ','ADMIN','20130905135336',' ',' ');
   END LOOP;
END;
/


